/**
 * Checks every internal link in a built site: that the page it names exists,
 * and that the anchor it names exists on that page.
 *
 *   node scripts/check-site-links.mjs _site
 *
 * Anchors are the reason this has to run against the *built* site rather than
 * the markdown. Heading ids are generated by kramdown, and GitHub generates its
 * own by a different rule, so a `#section` link can be correct in one place and
 * dangling in the other. Comparing the link to the id that was actually
 * emitted is the only reading that settles it.
 *
 * Links that leave docs/ — source files, the README, the Dockerfile — have no
 * page here by design: the layout rewrites them to the repository in the
 * browser. They are counted and reported rather than checked, because what
 * they resolve to is not in this directory.
 */
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative, normalize, dirname } from "node:path";

const root = process.argv[2];
if (!root) {
  console.error("usage: check-site-links.mjs <built-site-dir>");
  process.exit(2);
}

const pages = [];
const walk = (dir) => {
  for (const entry of readdirSync(dir)) {
    const path = join(dir, entry);
    if (statSync(path).isDirectory()) walk(path);
    else if (entry.endsWith(".html")) pages.push(path);
  }
};
walk(root);

/** Every id a page emits, so an anchor can be checked against what exists. */
const idsByPage = new Map(
  pages.map((path) => [
    relative(root, path),
    new Set([...readFileSync(path, "utf8").matchAll(/id="([^"]+)"/g)].map((m) => m[1])),
  ]),
);

const broken = [];
let checked = 0;
let offsite = 0;

/**
 * Checks every link in one fragment. The chrome and the body are separate
 * fragments because the chrome is identical on every page: checking it
 * everywhere would report one dead masthead link thirty-eight times, and
 * checking it nowhere is what let one ship — `Findings`, still in the header
 * after the document moved out of the site.
 */
const checkLinks = (fragment, page, docDir, label = page) => {
  // Anchors only. The chrome also carries a stylesheet and a favicon, which
  // are assets rather than pages and are not this script's business.
  for (const [, href] of fragment.matchAll(/<a\s[^>]*href="([^"]+)"/g)) {
    if (/^([a-z]+:|\/\/)/i.test(href)) continue;

    const [target, anchor] = href.split("#");
    let page_;

    if (!target) {
      page_ = page;
    } else if (href.startsWith("/")) {
      // Jekyll resolved it; it names a page here directly. `normalize("")`
      // is ".", so the site root has to be spelt out.
      const stripped = target.replace(/^\//, "");
      page_ = stripped === "" ? "" : normalize(stripped);
    } else {
      // Still relative, so the layout resolves it against the repository at
      // load. The same rule is applied here rather than skipped — leaving
      // these unchecked is what let two link bugs ship.
      const resolved = normalize(join(docDir, target));
      if (resolved === "README.md") page_ = "readme.html";
      else if (resolved.startsWith("docs/")) {
        page_ = resolved.slice(5).replace(/\.md$/, ".html").replace(/(^|\/)README\.html$/, "$1");
      } else {
        // Genuinely only in the repository.
        offsite++;
        continue;
      }
    }

    if (page_ === "" || page_.endsWith("/")) page_ += "index.html";

    checked++;
    if (!idsByPage.has(page_)) broken.push([label, href, `no such page (${page_})`]);
    else if (anchor && !idsByPage.get(page_).has(anchor)) broken.push([label, href, "no such anchor"]);
  }
};

/** Where a page's own relative links are written from. Everything is relative
 *  to docs/ except readme.html, which is the repository's README. */
const docDirOf = (page) =>
  page === "readme.html" ? "" : "docs/" + (dirname(page) === "." ? "" : dirname(page) + "/");

for (const path of pages) {
  const page = relative(root, path);
  const html = readFileSync(path, "utf8");
  checkLinks(html.split("<main", 2)[1] ?? html, page, docDirOf(page));
}

// The chrome, once, from the page that has the most of it open — the masthead
// and both reference shelves in the sidebar.
{
  const page = relative(root, pages.find((p) => relative(root, p) === "index.html") ?? pages[0]);
  const chrome = readFileSync(join(root, page), "utf8").split("<main", 2)[0];
  checkLinks(chrome, page, docDirOf(page), `${page} (chrome)`);
}

console.log(
  `${pages.length} pages · ${checked} internal links checked · ` +
    `${offsite} rewritten to the repository at load`,
);

for (const [page, href, why] of broken) console.error(`  ${page}  ${href}  — ${why}`);

if (broken.length > 0) {
  console.error(`\n${broken.length} broken link(s)`);
  process.exit(1);
}
console.log("every internal link resolves");
